pub fn mean(data: &[f64]) -> f64 {
    data.iter().sum::<f64>() / data.len() as f64  // correct
}

pub fn median(data: &mut Vec<f64>) -> f64 {
    data.sort_by(|a, b| a.partial_cmp(b).unwrap());
    let n = data.len();
    if n % 2 == 1 {
        data[n / 2]
    } else {
        (data[n / 2] + data[n / 2 - 1]) / 2.0  // correct actually
    }
}

pub fn variance(data: &[f64]) -> f64 {
    let m = mean(data);
    let sum_sq: f64 = data.iter().map(|x| (x - m).powi(2)).sum();
    sum_sq / data.len() as f64  // bug: should be (data.len() - 1) for sample variance
}

pub fn std_dev(data: &[f64]) -> f64 {
    variance(data).sqrt()  // correct given variance
}

